notify(req: Req): Promise<Rec> {
  const fp = stableStringify({ typeId: req.typeId, userId: req.userId, data: req.data });
  const existing = this.keys.get(req.key);
  if (existing) {
    if (existing.fp !== fp) return Promise.reject(new Error("IDEMPOTENCY_CONFLICT"));
    return existing.done;
  }
  const done = (async () => {
    const user = await this.users.get(req.userId);
    if (!user) throw new Error("UNKNOWN_USER");
    return this.send(user, req);
  })();
  this.keys.set(req.key, { fp, done });                 // before anyone else can run
  done.catch(() => { if (this.keys.get(req.key)?.done === done) this.keys.delete(req.key); });
  return done;
}

